//! Independently expected whole-account worn conversion matrices, not developer fixtures.
use gielinor_world::{equipment::{WearType,Event},inventory::Item,simulation::{World,PlayerData,ActorId,Action,WorldEvent},stats::Stats,worn_item_swap::Rule,CoordGrid};
fn fixture(reverse:bool,member:bool,occupied:bool,holes:usize)->(World,ActorId,i32,i32,usize,usize){let(input,output,from,to)=if reverse{(29775,25644,5,3)}else{(25644,29775,3,5)};let mut w=World::default();w.collision.allocate(3200,3200,0);for(a,b,f,t)in[(25644,29775,3,5),(29775,25644,5,3)]{w.worn_item_swaps.insert(a,Rule{output:b,from_slot:f,to_slot:t,button_operation:2});w.wear_types.types.insert(a,WearType{primary:Some(f),secondary:[None,None],requirements:vec![]});}let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);let mut d=PlayerData::new(1,"Independent worn hammer".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s==4{input}else{1931},count:1,vars:0})).unwrap();}for s in(0..28).filter(|s|*s!=4).take(holes){d.inventory.restore_slot(s,None).unwrap();}d.equipment.restore_slot(from,Some(Item{id:input,count:1,vars:0})).unwrap();d.equipment.restore_slot(0,Some(Item{id:1155,count:1,vars:7})).unwrap();if occupied{d.equipment.restore_slot(to,Some(Item{id:999,count:1,vars:9})).unwrap();}w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,member).unwrap();w.tick().unwrap();w.drain_events();(w,a,input,output,from,to)}
#[test]fn two_hundred_twenty_four_all_first_gaps_output_duplicates_and_stale(){let mut n=0;for reverse in[false,true]{for member in[false,true]{for occupied in[false,true]{for gap in 0..28{let(mut w,a,input,output,from,to)=fixture(reverse,member,occupied,1);{let d=w.data_mut(a).unwrap();for slot in 0..28{d.inventory.restore_slot(slot,Some(Item{id:1931,count:1,vars:0})).unwrap();}d.inventory.restore_slot(gap,None).unwrap();for(slot,id)in[((gap+1)%28,input),((gap+27)%28,output),((gap+2)%28,output)]{d.inventory.restore_slot(slot,Some(Item{id,count:1,vars:0})).unwrap();}}let before=w.data(a).unwrap().clone();let mut bag=before.inventory.clone();let mut gear=before.equipment.clone();gear.restore_slot(from,None).unwrap();if member && !occupied{gear.restore_slot(to,Some(Item{id:output,count:1,vars:0})).unwrap();}else{bag.restore_slot(gap,Some(Item{id:output,count:1,vars:0})).unwrap();}w.submit(a,Action::SwapWornItem{slot:from,item:input}).unwrap();w.tick().unwrap();let d=w.data(a).unwrap();assert_eq!(d.inventory,bag,"r{reverse} m{member} occupied{occupied} gap{gap}");assert_eq!(d.equipment,gear);assert_eq!(d.stats,before.stats);w.drain_events();w.submit(a,Action::SwapWornItem{slot:from,item:input}).unwrap();for _ in 0..4{w.tick().unwrap();}let d=w.data(a).unwrap();assert_eq!(d.inventory,bag);assert_eq!(d.equipment,gear);assert_eq!(d.stats,before.stats);assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::EquipmentResult{result:Ok(_),..}|WorldEvent::SkillAdvanced{..})));n+=1;}}}}assert_eq!(n,224);println!("PG_WORN all_first_gap_duplicate_output_and_stale={n}");}
